// This file is generated by AI.

// 编辑角色对话框。
//
// 角色的全部可编辑内容都在这里: 名称 / ID / 两个 GPT-SoVITS 模型 / 描述,
// 以及**下方的参考音频编辑列表** (搜索 / 增删 / 试听, 见 `ReferenceListEditor`)。
//
// 两个刻意的交互决定:
// * **改动即时生效**, 没有"保存"按钮 —— 输入框失焦、下拉选中、开关切换都会立刻落盘,
//   底部按钮只是"关闭"。用户填完就能直接看到列表里的变化。
// * 参考音频列表**自己滚动**, 而不是把整个对话框撑长: 整页滚动时标题栏与
//   "添加参考音频"按钮都会跑出视野。
//
// `hideModel` 用于「选择角色」对话框里点开的那一份: 那里只是想看看/改改这个角色的
// 参考音频, **权重是服务端本机的路径**, 与"这个角色叫什么、有哪些参考音频"无关,
// 摆在那里只会让人以为改它就能换音色。

import { Button, Field, Input, Textarea } from '@fluentui/react-components';
import { ArrowDownloadRegular } from '@fluentui/react-icons';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useRef, useState } from 'react';

import type { Character, ModelCandidate } from '../commands/voice';
import { voiceExportCharacter, type CharacterPatch } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { Select } from '../components/Select';
import { useAppStore } from '../state/store';
import { voiceController } from './controller';
import { ReferenceListEditor } from './ReferenceListEditor';

interface Props {
  character: Character;
  models: ModelCandidate[];
  /** 隐藏「GPT-SoVITS 模型」一项 (在「选择角色」里点开时) */
  hideModel?: boolean;
  onClose: () => void;
  /**
   * 内容已变化, 参数是**落盘后的这一份**。
   *
   * 必须是新对象而不是"让调用方拿旧 id 去查": 改角色 ID 时旧 id 已经不存在了,
   * 调用方按旧 id 查会查不到, 于是界面表现为"输入 ID 之后对话框自己关掉了"。
   */
  onChanged: (character: Character) => void;
  onError: (error: string | null) => void;
}

export function RoleEditDialog({ character, models, hideModel = false, onClose, onChanged, onError }: Props) {
  const [draft, setDraft] = useState(character);
  /** 已经落盘的 id; 与 `draft.id` 不同表示用户改了 id (需要搬移参考音频目录) */
  const savedId = useRef(character.id);

  useEffect(() => {
    setDraft(character);
    savedId.current = character.id;
  }, [character.id, character.updatedAt]);

  /**
   * 立即落盘 (没有"保存"按钮)。
   *
   * 默认走**字段补丁** (`updateCharacter`): 只发送这一项改动, 服务端读-改-写,
   * 因此不会把别的字段回写成过时快照。
   *
   * 唯一例外是**改名**: `id` 本身变了, 没法用字段补丁表达 (服务端要据此搬移参考
   * 音频目录), 那种情况才发送整份记录。
   */
  const commit = async (patch: CharacterPatch) => {
    const next = { ...draft, ...patch } as Character;
    setDraft(next);
    try {
      const renamed = typeof patch.id === 'string' && patch.id !== savedId.current;
      const saved = renamed
        ? await voiceController.persistCharacter(next, savedId.current)
        : await voiceController.updateCharacter(savedId.current, patch);
      savedId.current = saved.id;
      setDraft(saved);
      onError(null);
      onChanged(saved);
    } catch (caught) {
      // 失败时回滚到已落盘的状态, 避免界面显示一个并不存在的 id
      setDraft((current) => ({ ...current, id: savedId.current }));
      onError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  /**
   * 参考音频增删后，把**列表**换成刚落盘的那一份。
   *
   * 只合并 `references`: 名称 / 描述这些字段可能还停在"正在输入、尚未失焦"的状态，
   * 整份覆盖会把用户刚敲的字抹掉。
   */
  const syncReferences = () => {
    const latest = useAppStore.getState().voiceCharacters.find((item) => item.id === savedId.current);
    if (!latest) return;
    const merged = { ...draft, references: latest.references };
    setDraft(merged);
    onChanged(merged);
  };

  const exportCharacter = async () => {
    const destination = await saveDialog({
      defaultPath: `${draft.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  };

  /** 权重路径的后缀名 (权重文件名的可读部分) */
  const suffixOf = (weights: string | null | undefined): string => {
    if (!weights) return '';
    const name = weights.replace(/\\/g, '/').split('/').pop() ?? weights;
    return name;
  };

  return (
    <AppDialog
      title={`编辑角色 · ${character.name}`}
      size="large"
      height={640}
      compact
      onClose={onClose}
      footerLeading={
        <Button appearance="secondary" icon={<ArrowDownloadRegular />} onClick={() => void exportCharacter()}>
          导出角色
        </Button>
      }
      footer={
        <Button appearance="primary" onClick={onClose}>
          关闭
        </Button>
      }
    >
      <div className="role-edit-form">
        <Field label="角色名">
          <Input
            value={draft.name}
            placeholder="角色名"
            onChange={(_, data) => setDraft({ ...draft, name: data.value })}
            onBlur={() => void commit({ name: draft.name })}
          />
        </Field>

        <Field label="角色 ID">
          <Input
            value={draft.id}
            placeholder="角色 ID"
            title="同时是配置文件名与 game/vocal 下的目录名"
            onChange={(_, data) => setDraft({ ...draft, id: data.value })}
            onBlur={() => void commit({ id: draft.id })}
          />
        </Field>

        {!hideModel && (
          <Field label="GPT-SoVITS 模型" className="role-edit-span">
            <div className="role-edit-models">
              <Select
                placeholder="选择 GPT 权重"
                value={
                  models.some((item) => item.gptWeights === draft.model?.gptWeights) ? draft.model!.gptWeights! : ''
                }
                title={suffixOf(draft.model?.gptWeights) || '未指定 GPT 权重'}
                options={models.map((item) => ({ value: item.gptWeights, label: suffixOf(item.gptWeights) }))}
                onChange={(gptWeights) => void commit({ model: { ...(draft.model ?? {}), gptWeights } })}
              />
              <Select
                placeholder="选择 SoVITS 权重"
                value={
                  models.some((item) => item.sovitsWeights === draft.model?.sovitsWeights)
                    ? draft.model!.sovitsWeights!
                    : ''
                }
                title={suffixOf(draft.model?.sovitsWeights) || '未指定 SoVITS 权重'}
                options={models.map((item) => ({ value: item.sovitsWeights, label: suffixOf(item.sovitsWeights) }))}
                onChange={(sovitsWeights) => void commit({ model: { ...(draft.model ?? {}), sovitsWeights } })}
              />
            </div>
          </Field>
        )}

        <Field label="描述" className="role-edit-span">
          <Textarea
            className="character-description"
            resize="vertical"
            value={draft.description}
            onChange={(_, data) => setDraft({ ...draft, description: data.value })}
            onBlur={() => void commit({ description: draft.description })}
          />
        </Field>
      </div>

      {/* 参考音频列表 (搜索 + 增删 + 试听), 与「选择参考音频」对话框是同一个组件 */}
      <ReferenceListEditor character={draft} onChanged={syncReferences} />
    </AppDialog>
  );
}
